	title 'QD SLABS             GS ROM 3.0'*****************************************************************			   **                   SLABS		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1988	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   ***************************************************************************************************************************************** Change History** 9 Sep 88	Steven Glass** Rewrote slab routines to use both words of Pat no matter what the* mode.** Unwound the loop in FastSlabCopy and FastSlabXOR for case where* Pat and Pat+2 are the same.** 2/1/89	Mensch** Modified a few of the fast slab routines so they use a faster addressing mode*** 2/13/89	Dave Good** Changed the FastSlabCopy and FastSlabXOR routines to save a few bytes* and cycles** 4/22/89	Mensch* * Added SwapPat macro to test the startword and swap pat and pat+2 if the* startwprd starts on an odd word. This should fix 320 pattern fills and* 640 mode pattern fills that use arcrot.***********************************************************************	blanks off	string asis	include 'all.macros'	include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:CORE.GLOBALS1'	INCLUDE ':QDEquates:core.globals2'	INCLUDE ':QDEquates:region.equs'	INCLUDE ':QDEquates:RECT.EQUS'	INCLUDE ':QDEquates:SLAB.EQUS'	macro	SwapPat; This macro will test to see if the patter needs to be swapped and it will do so if ; it needs it. I only do it here as an 11th hour fix to a dastardly problem	lda <StartWord	; get the starting word number	and #$0002	; see if its an odd word or even word	beq @NoSwapNeeded	; if zero, don't swap	ldx <pat	lda <pat+2	sta <pat	stx <Pat+2	ldx <DrawMask	lda <DrawMask+2	sta <DrawMask	stx <DrawMask+2@NoSwapNeeded		; now continue	ENDM	****************************************************************** All the slab routines use the same data on zero page.** Before any slab routine is called, the data bank register* is set to the bank containing the pixel map.** The following are	set up on zero page	before this routine* is called:** Inputs:**    LeftMask      The Pixels not being	touched on the left	are*                  set to zero in this word mask.**    RightMask     The Pixels not being	touched on the right are*                  set to zero in this word mask**    StartWord     The First word on the scan line to deal with**    FinishWord    The last word on the	scan line to deal with**    ScanMaskRef   Points to the global	scan line clip buffer**    DestRef       Points to the start of the current scan line*                  (or scan line equiv since can draw into mem).**    PatMask       A mask to use with current index into scan line*                  to produce an index into Pat.  In 320 mode,*                  PatMask AND Index will yield 0 or 2.  In	640 mode*                  it will always yield	0 since pattern fits in*                  one word**    Pat           Two words to hold the current part of the*                  pattern being used for this scan line.**    DrawMask      Two words to hold the current slice of the*                  of the drawing mask.******************************************************************	title 'SlabCopy'*****************************************************************SlabCopy	PROC EXPORT** This is the routine that is called to copy patterns to* the destination when the regions are non-rectangular or the* penmask is not all $FFFF's.*** Inputs:**    LeftMask      The Pixels not being	touched on the left	are*                  set to zero in this word mask.**    RightMask     The Pixels not being	touched on the right are*                  set to zero in this word mask**    StartWord     The First word on the scan line to deal with**    FinishWord    The last word on the	scan line to deal with**    ScanMaskRef   Points to the global	scan line clip buffer**    DestRef       Points to the start of the current scan line*                  (or scan line equiv since can draw into mem).**    PatMask       A mask to use with current index into scan line*                  to produce an index into Pat.  In 320 mode,*                  PatMask AND Index will yield 0 or 2.  In	640 mode*                  it will always yield	0 since pattern fits in*                  one word**    Pat           Two words to hold the current part of the*                  pattern being used for this scan line.**    DrawMask      Two words to hold the current slice of the*                  of the drawing mask.**** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 08 Sep 88	Steven Glass** Unwound the loop some and took advantage of the expanded* pattern.** No counters are kept on direct page.*****************************************************************	SwapPat	lda FinishWord	; put count in x-register	sec	sbc StartWord	lsr a	; make this num words to xfer - 1	tax		ldy StartWord	; get the start word in y	lda Pat	; source pattern in a-reg	eor (DestRef),y	; invert with dest	and LeftMask	cpx #0	; check for special case where only 1 word	bne @MoreThanOne	and RightMask@MoreThanOne	and [ScanMaskRef],y ; do masking	and DrawMask	eor (DestRef),y	; invert again	sta (DestRef),y	; and store	cpx #0	beq AllDone	iny	; bump y and but don't touch x yet	iny	cpx #1	; if x is 1 there is one word to go	beq DoLastWord2	dexInnerLoop	lda Pat+2	; source pattern in a-reg	eor (DestRef),y	; invert with dest	and [ScanMaskRef],y ; do masking	and DrawMask+2	eor (DestRef),y	; invert again	sta (DestRef),y	; and store	iny	; bump y	iny	dex	; dec x	beq DoLastWord1	; if x is zero there is one word to go	lda Pat	eor (DestRef),y	and [ScanMaskRef],y	and DrawMask	eor (DestRef),y	sta (DestRef),y	iny	iny	dex	bne InnerLoop	; if x is zero there is one word to goDoLastWord2	lda Pat+2	; source pattern in a-reg	eor (DestRef),y	; invert with dest	and RightMask	and [ScanMaskRef],y ; do masking	and DrawMask+2	eor (DestRef),y	; invert again	sta (DestRef),y	; and storeAllDone		SwapPat	rtlDoLastWord1	lda Pat	; source pattern in a-reg	eor (DestRef),y	; invert with dest	and RightMask	and [ScanMaskRef],y ; do masking	and DrawMask	eor (DestRef),y	; invert again	sta (DestRef),y	; and store	SwapPat	rtl	ENDP	title 'SlabOR'*****************************************************************SlabOR	PROC EXPORT** This is the routine that is called to OR patterns to* the destination when the regions are non-rectangular or the* penmask is not all $FFFF's.*** Inputs:**    LeftMask      The Pixels not being	touched on the left	are*                  set to zero in this word mask.**    RightMask     The Pixels not being	touched on the right are*                  set to zero in this word mask**    StartWord     The First word on the scan line to deal with**    FinishWord    The last word on the	scan line to deal with**    ScanMaskRef   Points to the global	scan line clip buffer**    DestRef       Points to the start of the current scan line*                  (or scan line equiv since can draw into mem).**    PatMask       A mask to use with current index into scan line*                  to produce an index into Pat.  In 320 mode,*                  PatMask AND Index will yield 0 or 2.  In	640 mode*                  it will always yield	0 since pattern fits in*                  one word**    Pat           Two words to hold the current part of the*                  pattern being used for this scan line.**    DrawMask      Two words to hold the current slice of the*                  of the drawing mask.**** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 08 Sep 88	Steven Glass** Unwound the loop some and took advantage of the expanded* pattern.** No counters are kept on direct page.*****************************************************************	swapPat	lda FinishWord	; put count in x-register	sec	sbc StartWord	lsr a	; make this num words to xfer - 1	tax		ldy StartWord	; get the start word in y	lda Pat	; source pattern in a-reg	and LeftMask	cpx #0	; check for special case where only 1 word	bne @MoreThanOne	and RightMask@MoreThanOne	and [ScanMaskRef],y ; do masking	and DrawMask	ORA (DestRef),y	; OR	sta (DestRef),y	; and store	cpx #0	beq AllDone	iny	; bump y and but don't touch x yet	iny	cpx #1	; if x is 1 there is one word to go	beq DoLastWord2	dexInnerLoop	lda Pat+2	; source pattern in a-reg	and [ScanMaskRef],y ; do masking	and DrawMask+2	ORA (DestRef),y	; OR	sta (DestRef),y	; and store	iny	; bump y	iny	dex	; dec x	beq DoLastWord1	; if x is zero there is one word to go	lda Pat	and [ScanMaskRef],y	and DrawMask	ORA (DestRef),y	sta (DestRef),y	iny	iny	dex	bne InnerLoop	; if x is zero there is one word to goDoLastWord2	lda Pat+2	; source pattern in a-reg	and RightMask	and [ScanMaskRef],y ; do masking	and DrawMask+2	ORA (DestRef),y	; invert again	sta (DestRef),y	; and storeAllDone		SwapPat	rtlDoLastWord1	lda Pat	; source pattern in a-reg	and RightMask	and [ScanMaskRef],y ; do masking	and DrawMask	ORA (DestRef),y	; invert again	sta (DestRef),y	; and store	SwapPat	rtl	ENDP	title 'SlabXOR'*****************************************************************SlabXOR	PROC EXPORT** This is the routine that is called to XOR patterns to* the destination when the regions are non-rectangular or the* penmask is not all $FFFF's.*** Inputs:**    LeftMask      The Pixels not being	touched on the left	are*                  set to zero in this word mask.**    RightMask     The Pixels not being	touched on the right are*                  set to zero in this word mask**    StartWord     The First word on the scan line to deal with**    FinishWord    The last word on the	scan line to deal with**    ScanMaskRef   Points to the global	scan line clip buffer**    DestRef       Points to the start of the current scan line*                  (or scan line equiv since can draw into mem).**    PatMask       A mask to use with current index into scan line*                  to produce an index into Pat.  In 320 mode,*                  PatMask AND Index will yield 0 or 2.  In	640 mode*                  it will always yield	0 since pattern fits in*                  one word**    Pat           Two words to hold the current part of the*                  pattern being used for this scan line.**    DrawMask      Two words to hold the current slice of the*                  of the drawing mask.**** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 08 Sep 88	Steven Glass** Unwound the loop some and took advantage of the expanded* pattern.** No counters are kept on direct page.*****************************************************************	swapPat	lda FinishWord	; put count in x-register	sec	sbc StartWord	lsr a	; make this num words to xfer - 1	tax		ldy StartWord	; get the start word in y	lda Pat	; source pattern in a-reg	and LeftMask	cpx #0	; check for special case where only 1 word	bne @MoreThanOne	and RightMask@MoreThanOne	and [ScanMaskRef],y ; do masking	and DrawMask	eor (DestRef),y	; XOR	sta (DestRef),y	; and store	cpx #0	beq AllDone	iny	; bump y and but don't touch x yet	iny	cpx #1	; if x is 1 there is one word to go	beq DoLastWord2	dexInnerLoop	lda Pat+2	; source pattern in a-reg	and [ScanMaskRef],y ; do masking	and DrawMask+2	eor (DestRef),y	; EOR	sta (DestRef),y	; and store	iny	; bump y	iny	dex	; dec x	beq DoLastWord1	; if x is zero there is one word to go	lda Pat	and [ScanMaskRef],y	and DrawMask	eor (DestRef),y	sta (DestRef),y	iny	iny	dex	bne InnerLoop	; if x is zero there is one word to goDoLastWord2	lda Pat+2	; source pattern in a-reg	and RightMask	and [ScanMaskRef],y ; do masking	and DrawMask+2	eor (DestRef),y	; XOR	sta (DestRef),y	; and storeAllDone	SwapPat	rtlDoLastWord1	lda Pat	; source pattern in a-reg	and RightMask	and [ScanMaskRef],y ; do masking	and DrawMask	eor (DestRef),y	; XOR	sta (DestRef),y	; and store	SwapPat	rtl	ENDP	title 'SlabBIC'*****************************************************************SlabBIC	PROC EXPORT** This is the routine that is called to BIC patterns to* the destination when the regions are non-rectangular or the* penmask is not all $FFFF's.*** Inputs:**    LeftMask      The Pixels not being	touched on the left	are*                  set to zero in this word mask.**    RightMask     The Pixels not being	touched on the right are*                  set to zero in this word mask**    StartWord     The First word on the scan line to deal with**    FinishWord    The last word on the	scan line to deal with**    ScanMaskRef   Points to the global	scan line clip buffer**    DestRef       Points to the start of the current scan line*                  (or scan line equiv since can draw into mem).**    PatMask       A mask to use with current index into scan line*                  to produce an index into Pat.  In 320 mode,*                  PatMask AND Index will yield 0 or 2.  In	640 mode*                  it will always yield	0 since pattern fits in*                  one word**    Pat           Two words to hold the current part of the*                  pattern being used for this scan line.**    DrawMask      Two words to hold the current slice of the*                  of the drawing mask.**** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 08 Sep 88	Steven Glass** Unwound the loop some and took advantage of the expanded* pattern.** No counters are kept on direct page.*****************************************************************	swapPat	lda FinishWord	; put count in x-register	sec	sbc StartWord	lsr a	; make this num words to xfer - 1	tax		ldy StartWord	; get the start word in y	lda Pat	; source pattern in a-reg	and LeftMask	cpx #0	; check for special case where only 1 word	bne @MoreThanOne	and RightMask@MoreThanOne	and [ScanMaskRef],y ; do masking	and DrawMask	eor #$FFFF	; invert	and (DestRef),y	; AND	sta (DestRef),y	; and store	cpx #0	beq AllDone	iny	; bump y and but don't touch x yet	iny	cpx #1	; if x is 1 there is one word to go	beq DoLastWord2	dexInnerLoop	lda Pat+2	; source pattern in a-reg	and [ScanMaskRef],y ; do masking	and DrawMask+2	eor #$FFFF	; invert	and (DestRef),y	; AND	sta (DestRef),y	; and store	iny	; bump y	iny	dex	; dec x	beq DoLastWord1	; if x is zero there is one word to go	lda Pat	and [ScanMaskRef],y	and DrawMask	eor #$FFFF	; invert	and (DestRef),y	sta (DestRef),y	iny	iny	dex	bne InnerLoop	; if x is zero there is one word to goDoLastWord2	lda Pat+2	; source pattern in a-reg	and RightMask	and [ScanMaskRef],y ; do masking	and DrawMask+2	eor #$FFFF	; invert	and (DestRef),y	; AND	sta (DestRef),y	; and storeAllDone	SwapPat	rtlDoLastWord1	lda Pat	; source pattern in a-reg	and RightMask	and [ScanMaskRef],y ; do masking	and DrawMask	eor #$FFFF	; invert	and (DestRef),y	; XOR	sta (DestRef),y	; and store	SwapPat	rtl	ENDP	title 'FastSlabs'****************************************************************** FastSlabs** Summary.** The fast slab routines are called when the object being drawn* is not clipped to	a non-rectangular region and the Drawing mask* is all FFFF's.  This makes drawing faster since I don't have* to access the scan line mask buffer and do all the other work* associated with masking.** All the slab routines use the same data on zero page.** Before any slab routine is called, the data bank register* is set to the bank containing the pixel image.** The following are	set up on zero page	before this routine* is called:** Inputs:**    LeftMask      The Pixels not being	touched on the left	are*                  set to zero in this word mask.**    RightMask     The Pixels not being	touched on the right are*                  set to zero in this word mask**    StartWord     The First word on the scan line to deal with**    FinishWord    The last word on the	scan line to deal with**    DestRef       Points to the start of the current scan line*                  (or scan line equiv since can draw into mem).**    Pat           Two words to hold the current part of the*                  pattern being used for this scan line.**** Variables**    Temp	this is destroyed by the FastCopy and FastXOR*	routines. All the other routines don't change*	any direct page values******************************************************************	title 'FastSlabXOR'*****************************************************************FastSlabXOR	PROC EXPORT** This is the code that is run when QuickDraw discovers* that the object being drawn is not being clipped to a* irregular region and the pen mask is all $FFFF.*** Inputs:**    LeftMask      The Pixels not being	touched on the left	are*                  set to zero in this word mask.**    RightMask     The Pixels not being	touched on the right are*                  set to zero in this word mask**    StartWord     The First word on the scan line to deal with**    FinishWord    The last word on the	scan line to deal with**    DestRef       Points to the start of the current scan line*                  (or scan line equiv since can draw into mem).**    Pat           Two words to hold the current part of the*                  pattern being used for this scan line.**** Variables:**    Temp	this is destroyed.**** Outputs:**    none** External Refs:*	IMPORT  IncrementDataBank** Entry Points:**    none*	longa on	; mode	longi on*** Change History** 09 Sep 88	Steven Glass** Adjusted code to use both words of Pat for all modes.** Wrote new special case code to be used when Pat and Pat+2* are the same.** No longer writes to direct page.*** 18 Jan 89	Dave Good** Rewrote to remove iny's from the special case loop. Many other* changes to remove bytes and cycles. This code now writes to* direct page again** 3/9/89	Mensch* Added an Alt entry point for fast rect slabs*****************************************************************;---------------------------------------------------------------MaxWordsInRow	equ  80MaxBytesInRow	equ  MaxWordsInRow*2;---------------------------------------------------------------	Export FastSlabXORAlt	Export EndXORRazor	MACRO	EORMultiple	LCLA  &counter&counter	SETA MaxBytesInRow	WHILE  &counter > 0  DO	txa	eor  |&counter,y	sta  |&counter,y&counter	SETA &counter-2	ENDWHILE	MEND;---------------------------------------------------------------;---------------------------------------------------------------	SwapPat	lda  FinishWord		;get the number of bytes to XOR into the	sec		;..A-Reg	sbc  StartWord	beq  doSingleWord		;if only one word, do a special case	lsr  a	dec  a		;if only two words, then do another	beq  doLastTwo		;..special case	tax		;otherwise the count goes in X-Reg	lda  Pat		;if the patterns are equal go very fast	cmp  Pat+2	beq  GoReallyFastFastSlabXORAlt	ldy  StartWord		;get the start word in y	lda  Pat		;first source pattern in A-Reg	and  LeftMask	eor  (DestRef),y		;invert & store it	sta  (DestRef),y	iny		;increment our index	iny;---------------------------------------------------------------@loop	lda  Pat+2		;second source pattern in A-Reg	eor  (DestRef),y		;invert & store it	sta  (DestRef),y	iny		;increment our index	iny	dex		;decrement our counter	beq  doLastWord1		;if we're done, then do the last	lda  Pat		;back to first source pattern	eor  (DestRef),y	sta  (DestRef),y	iny	iny	dex	bne  @loop;---------------------------------------------------------------doLastWord2	lda  Pat+2		;second source pattern in A-RegdoLastWord	and  RightMask	eor  (DestRef),y		;invert & store it	sta  (DestRef),y	SwapPat	rtldoLastWord1	lda  Pat		;first source pattern in A-Reg	bra  doLastWorddoSingleWord	ldy  StartWord		;do only one word	lda  Pat	and  LeftMask	bra  doLastWord		;save bytes here by reusing codedoLastTwo	ldy  StartWord		;invert the first word with the first	lda  Pat		;..pattern	and  LeftMask	eor  (DestRef),y	sta  (DestRef),y	iny		;move to the second and last word	iny	bra  doLastWord2		;..go invert it with the second pattern;---------------------------------------------------------------;---------------------------------------------------------------GoReallyFast	phb		;save the bank register (we will change it)	lda  StartWord		;make Y-Reg a pointer to the first word	clc		;..to invert	adc  DestRef	tay	bcc  @1		;if Y-Reg overflows, then we must bump the	jsr  IncrementDataBank	;..bank register@1	lda  Pat		;invert our first word using the only	and  LeftMask		;..pattern and leftMask	eor  |0,y	sta  |0,y	txa		;put our count in X-Reg and our single	ldx  Pat		;..pattern in X-Reg;---------------------------------------------------------------rowLoop	cmp  #MaxWordsInRow		;compare the count with our maximum row size	blt  doLastRow		;..size. If less, then do last row	sbc  #MaxWordsInRow		;adjust our count (carry is always SET)	pha		;save the count on the stack	jsr  DoEntireRow		;XOR the row	tya		;move our pointer (Y-Reg) past the bytes	clc		;..we just inverted.	adc  #MaxBytesInRow	tay	bcc  @noBump		;check for overflow	jsr  IncrementDataBank	;if overflow, then bump the bank@noBump	pla		;get back the count and loop	bra  rowLoop;---------------------------------------------------------------doLastRow	sta  Temp		;save the count in direct page	asl  a		;multiply the count by seven (the number	asl  a		;..of bytes of code it takes to XOR one	asl  a		;..word.)	sbc  Temp		;NOTE: the carry is always CLR here so	eor  #$FFFF		;..these three lines get us:	adc  #EndXORRazor-2		;..{ EndXORRazor - (count * 7) - 1 }	pea  returnAddr-1		;this is where we want to return to	pha	rts		;jump to our block XOR;---------------------------------------------------------------returnAddr	plb		;restore the original bank	ldy  FinishWord		;the last word is always at finish word	txa		;source pattern is still in X-Reg	and  RightMask	eor  (DestRef),y	sta  (DestRef),y		;and store	SwapPat	rtl;---------------------------------------------------------------;---------------------------------------------------------------DoEntireRow	EORMultipleEndXORRazor	rts;---------------------------------------------------------------	ENDP****************************************************************	title 'FastSlabCopy'*****************************************************************FastSlabCopy	PROC EXPORT** This is the code that is run when QuickDraw discovers* that the object being drawn is not being clipped to a* irregular region and the pen mask is all $FFFF.*** Inputs:**    LeftMask      The Pixels not being	touched on the left	are*                  set to zero in this word mask.**    RightMask     The Pixels not being	touched on the right are*                  set to zero in this word mask**    StartWord     The First word on the scan line to deal with**    FinishWord    The last word on the	scan line to deal with**    DestRef       Points to the start of the current scan line*                  (or scan line equiv since can draw into mem).**    Pat           Two words to hold the current part of the*                  pattern being used for this scan line.**** Variables:**    Temp	this is destroyed.**** Outputs:**    none** External Refs:*	IMPORT  IncrementDataBank** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 09 Sep 88	Steven Glass** Adjusted code to use both words of Pat for all modes.** Wrote new special case code to be used when Pat and Pat+2* are the same.** No longer writes to direct page.*** 16 Nov 88	Steven Glass** The count for MaxInRow was off by one making us draw two few bytes* for each time through the loop.** Also added an entry in the RowTable for 0 words.  This is* unlikely, but possible if the number of words to do is* equal to the maxInRow.*** 18 Jan 89	Dave Good** Completely Rewrote to remove iny's from the special case* loop. This routine now uses direct page again*****************************************************************;---------------------------------------------------------------MaxWordsInRow	equ  80MaxBytesInRow	equ  MaxWordsInRow*2;---------------------------------------------------------------	MACRO	STAMultiple	LCLA  &counter&counter	SETA  MaxBytesInRow	WHILE  &counter > 0  DO	sta  |&counter,y&counter	SETA  &counter-2	ENDWHILE	MEND;---------------------------------------------------------------	MACRO&lab	MakeJumpTable	LCLA  &counter&counter	SETA  0&lab	WHILE  &counter < MaxWordsInRow  DO	dc.w  EndAddr-(&counter*3)&counter	SETA &counter+1	ENDWHILE	MEND;---------------------------------------------------------------;---------------------------------------------------------------	SwapPat	lda  FinishWord		;get the number of bytes to copy into	sec		;..A-Reg	sbc  StartWord	beq  doSingleWord		;if only one word, do a special case	lsr  a	dec  a		;if only two words, then do another	beq  doLastTwo		;..special case	tax		;otherwise the count goes in X-Reg	lda  Pat		;if the patterns are equal go very fast	cmp  Pat+2	beq  GoReallyFast	Export FastSlabCopyAltFastSlabCopyAlt	ldy  StartWord		;get the start word in Y-Reg	lda  Pat		;first source pattern in A-Reg	eor  (DestRef),y		;clip with the mask properly	and  LeftMask	eor  (DestRef),y	sta  (DestRef),y		;and store	iny		;increment our index	iny;---------------------------------------------------------------@loop	lda  Pat+2		;second source pattern in A-Reg	sta  (DestRef),y	iny		;increment our index	iny	dex		;decrement our counter	beq  doLastWord1		;if we're done, then do the last	lda  Pat	sta  (DestRef),y	iny	iny	dex	bne  @loop;---------------------------------------------------------------doLastWord2	lda  Pat+2		;second source pattern in A-RegdoLastWord	eor  (DestRef),y		;clip with the mask properlyexit	and  RightMask	eor  (DestRef),y	sta  (DestRef),y		;and store	SwapPat	rtldoLastWord1	lda  Pat		;first source pattern in a-reg	bra  doLastWorddoSingleWord	ldy  StartWord		;do the first and only word here using	lda  Pat		;..the first source pattern	eor  (DestRef),y	and  LeftMask	bra  exit		;save bytes heredoLastTwo	ldy  StartWord		;do the first word here with the first	lda  Pat		;source pattern	eor  (DestRef),y	and  LeftMask	eor  (DestRef),y	sta  (DestRef),y	iny		;move to the next and last word and use	iny		;..the second source pattern.	bra  doLastWord2		;save bytes here;---------------------------------------------------------------;---------------------------------------------------------------GoReallyFast	phb		;save the bank register (we will change it)	lda  StartWord		;make Y-Reg into a pointer to the first	clc		;..word	adc  DestRef	tay	bcc  @1		;if Y-Reg overflows, then we must bump	jsr  IncrementDataBank	;..the bank register@1	lda  Pat		;copy into the first word using leftMask	eor  |0,y		;..to clip it.	and  LeftMask	eor  |0,y	sta  |0,y	txa		;put our counter in the A-Reg;---------------------------------------------------------------rowLoop	cmp  #MaxWordsInRow		;compare the count with our maximum row size	blt  doLastRow		;..size. If less, then do last row	sbc  #MaxWordsInRow		;adjust our count (carry is always SET)	pha		;save the count on the stack	lda  Pat	jsr  DoEntireRow		;COPY the row	tya		;move our pointer (Y-Reg) past the bytes	clc		;..we just inverted.	adc  #MaxBytesInRow	tay	bcc  @noBump		;check for overflow	jsr  IncrementDataBank	;if overflow, then bump the bank@noBump	pla		;get back the count and loop	bra  rowLoop;---------------------------------------------------------------doLastRow	asl  a		;multiply the count by two and use this	tax		;..as our index into the jump table	lda  Pat	jsr  (JumpTable,x);---------------------------------------------------------------returnAddr	plb		;restore the original data bank	ldy  FinishWord		;the last word is always at finish word	lda  Pat		;only source pattern in a-reg	eor  (DestRef),y		;clip with the mask properly	and  RightMask	eor  (DestRef),y	sta  (DestRef),y		;and store	SwapPat	rtl;---------------------------------------------------------------;---------------------------------------------------------------DoEntireRow	STAMultipleEndAddr	rts;---------------------------------------------------------------	Export CopyJumpTableCopyJumpTableJumpTable	MakeJumpTable;---------------------------------------------------------------	ENDP****************************************************************	title 'IncrementDataBank'*****************************************************************IncrementDataBank	PROC ENTRY** This increments the bank register by one*** Inputs:**    none** Outputs:**    none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 03 Feb 89	Dave Good** This routine is used by FastSlabCopy and FastSlabXOR to* increment the data bank.******************************************************************	phb		;put the data bank on the stack	pla		;get back $xxbb where bb is the data bank	inc  a		;increment the bank. Note: this will NEVER	pha		;..wrap to the next byte	plb		;get the data bank back in B	rts	ENDP****************************************************************	title 'FastSlabOr'*****************************************************************FastSlabOr	PROC EXPORT** This is the code that is run when QuickDraw discovers* that the object being drawn is not being clipped to a* irregular region and the pen mask is all $FFFF.*** Inputs:**    LeftMask      The Pixels not being	touched on the left	are*                  set to zero in this word mask.**    RightMask     The Pixels not being	touched on the right are*                  set to zero in this word mask**    StartWord     The First word on the scan line to deal with**    FinishWord    The last word on the	scan line to deal with**    DestRef       Points to the start of the current scan line*                  (or scan line equiv since can draw into mem).**    Pat           Two words to hold the current part of the*                  pattern being used for this scan line.***** Outputs:**    none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	swapPat	lda FinishWord	; put count in x-register	sec	sbc StartWord	lsr a	; div by 2 so holds num words to xfer - 1	tax	;	lda StartWord	; get the start word in y;	clc	; this carry is already always cleared by lsr above	;	adc destRef;	tay	; this is the offset to out slab...	ldy StartWord	lda Pat	; source pattern in a-reg	and LeftMask	cpx #0	; check for special case where only 1 word	bne @MoreThanOne	and RightMask@MoreThanOne	ora (destRef),y	; invert again	sta (destRef),y	; and store	cpx #0	beq AllDone	iny	; bump y and but don't touch x yet	iny	dex	; dec x since one word is done	bne innerLoop	bra DoLastWord2innerLoop;	txa;	asl a;	pha;; the following code was generated with the following MPW shell script; use it in good health commander;set x 8;set y 0;Loop;    echo "¶tlda pat+2" ;;    echo "¶teor |{y},y" ;;    echo "¶tsta |{y},y" ;;    echo "¶tdex";    echo "¶tbeq DoLastWord2";	 set y `evaluate {y}+2`;;    echo "¶tlda pat" ;;    echo "¶teor |{y},y" ;;    echo "¶tsta |{y},y" ;;    echo "¶tdex";    echo "¶tbeq DoLastWord1";	 set y `evaluate {y}+2`;;    set x `evaluate {x}-1` ;;    If {X}>1 ;        continue;    else;        break;    end;;End  	lda Pat+2	; source pattern in a-reg	ora (DestRef),y	; OR	sta (DestRef),y	; and store;;	iny	; bump y	iny	;	dex	; dec x	beq DoLastWord1	; if x is zero there is one word to go;	lda Pat	ora (DestRef),y	; OR	sta (DestRef),y	; and store;	iny	iny	dex	bne InnerLoop	; if x is zero there is one word to goDoLastWord2	lda Pat+2	; source pattern in a-reg	and RightMask	ora (DestRef),y	; OR	sta (DestRef),y	; and storeAllDone	SwapPat	rtlDoLastWord1	lda Pat	; source pattern in a-reg	and RightMask	ora (DestRef),y	; OR	sta (DestRef),y	; and store	SwapPat	rtl	ENDP	title 'FastSlabBIC'*****************************************************************FastSlabBIC	PROC EXPORT** This is the code that is run when QuickDraw discovers* that the object being drawn is not being clipped to a* irregular region and the pen mask is all $FFFF.*** Inputs:**    LeftMask      The Pixels not being	touched on the left	are*                  set to zero in this word mask.**    RightMask     The Pixels not being	touched on the right are*                  set to zero in this word mask**    StartWord     The First word on the scan line to deal with**    FinishWord    The last word on the	scan line to deal with**    DestRef       Points to the start of the current scan line*                  (or scan line equiv since can draw into mem).**    Pat           Two words to hold the current part of the*                  pattern being used for this scan line.***** Outputs:**    none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	SwapPat	lda FinishWord	; put count in x-register	sec	sbc StartWord	lsr a	; div by 2 so holds num words to xfer - 1	tax		ldy StartWord	; get the start word in y	lda Pat	; source pattern in a-reg	and LeftMask	cpx #0	; check for special case where only 1 word	bne @MoreThanOne	and RightMask@MoreThanOne	eor #$FFFF	; INVERT	and (DestRef),y	; AND	sta (DestRef),y	; and store	cpx #0	beq AllDone	iny	; bump y and but don't touch x yet	iny	cpx #1	; if x is 1 there is one word to go	beq DoLastWord2	dex	; dec x since one word is doneInnerLoop	lda Pat+2	; source pattern in a-reg	eor #$FFFF	; Invert	and (DestRef),y	; AND	sta (DestRef),y	; and store	iny	; bump y	iny	dex	; dec x	beq DoLastWord1	; if x is zero there is one word to go	lda Pat	eor #$FFFF	; INVERT	and (DestRef),y	; AND	sta (DestRef),y	; and store	iny	iny	dex	bne InnerLoop	; if x is zero there is one word to go (fall through)DoLastWord2	lda Pat+2	; source pattern in a-reg	and RightMask	eor #$FFFF	; invert	and (DestRef),y	; AND	sta (DestRef),y	; and storeAllDone	SwapPat	rtlDoLastWord1	lda Pat	; source pattern in a-reg	and RightMask	eor #$FFFF	; invert	and (DestRef),y	; AND	sta (DestRef),y	; and store	SwapPat	rtl	ENDP	END